style.css:
@-moz-document domain("roblox.com") {
body {
  background-image: url("https://files.catbox.moe/0r8b23.jpeg");
  background-size: cover;
  background-repeat: no-repeat;
  background-attachment: fixed;
  background-position: center;
  color: #fce4ec;
}

.container, .navbar, .content, .footer, .page-content, #nav-home {
  background: rgba(255, 255, 255, 0.7) !important;
  border-radius: 10px !important;
  backdrop-filter: blur(6px);
}

h1, h2, h3, h4, h5, p, span, a {
  color: #d37fa3 !important;
}

a:hover {
  color: #f7a8c2 !important;
  text-shadow: 0 0 8px #ffd1dc;
}

button, .btn {
  background-color: #f8cde0 !important;
  border: 1px solid #f7a8c2 !important;
  color: #fff !important;
  border-radius: 8px !important;
  transition: all 0.3s ease-in-out;
}

button:hover, .btn:hover {
  background-color: #f7a8c2 !important;
  box-shadow: 0 0 10px #ffd1dc;
}

.navbar {
  background: rgba(255, 240, 245, 0.8) !important;
  border-bottom: 1px solid #f7a8c2 !important;
}

::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: #fdeef4;
}
::-webkit-scrollbar-thumb {
  background: #f7a8c2;
  border-radius: 5px;
}
::-webkit-scrollbar-thumb:hover {
  background: #f39ab5;
}
}
